  </div>
</div>',
      title = 'Edit and Reuse Smart Lists',
      lesson_number = 10,
      sort_order = 10,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Edit and Reuse Smart Lists';
